struct HostNetworkInfo:Equatable{var hostName=Host.current().localizedName ?? ProcessInfo.processInfo.hostName;var ipv4:[String]=[];var ipv6:[String]=[];var interfaces:[String]=[];static func current()->HostNetworkInfo{var r=HostNetworkInfo();var p:UnsafeMutablePointer<ifaddrs>?;guard getifaddrs(&p)==0,let f=p else{return r};defer{freeifaddrs(p)};var c:UnsafeMutablePointer<ifaddrs>?=f;while let x=c{let i=x.pointee;c=i.ifa_next;guard let a=i.ifa_addr else{continue};let fam=Int32(a.pointee.sa_family);guard fam==AF_INET||fam==AF_INET6 else{continue};let fl=Int32(i.ifa_flags);guard(fl&IFF_UP) != 0,(fl&IFF_LOOPBACK)==0 else{continue};var h=[CChar](repeating:0,count:Int(NI_MAXHOST));let l:socklen_t=fam==AF_INET ? socklen_t(MemoryLayout<sockaddr_in>.size):socklen_t(MemoryLayout<sockaddr_in6>.size);guard getnameinfo(a,l,&h,socklen_t(h.count),nil,0,NI_NUMERICHOST)==0 else{continue};let raw=String(cString:h),v=raw.split(separator:"%",maxSplits:1).first.map(String.init) ?? raw,n=String(cString:i.ifa_name);if fam==AF_INET,!r.ipv4.contains(v){r.ipv4.append(v)};if fam==AF_INET6,!r.ipv6.contains(v){r.ipv6.append(v)};if !r.interfaces.contains(n){r.interfaces.append(n)}};return r}}
final class WolffeWebServer{let port:UInt16;var onState:((String,Bool)->Void)?;private var listener:NWListener?;private let q=DispatchQueue(label:"com.wolffetv.webserver");init(port:UInt16){self.port=port};func start()throws{guard let p=NWEndpoint.Port(rawValue:port)else{return};let l=try NWListener(using:.tcp,on:p);l.stateUpdateHandler={[weak self]s in switch s{case .ready:self?.onState?("Running",true);case .waiting(let e):self?.onState?("Waiting: \(e)",false);case .failed(let e):self?.onState?("Failed: \(e)",false);case .cancelled:self?.onState?("Stopped",false);default:break}};l.newConnectionHandler={[weak self]in self?.handle($0)};listener=l;l.start(queue:q)};func stop(){listener?.cancel();listener=nil;onState?("Stopped",false)};private func handle(_ c:NWConnection){c.start(queue:q);c.receive(minimumIncompleteLength:1,maximumLength:16384){[weak self]d,_,_,_ in self?.reply(c,d ?? Data())}};private func reply(_ c:NWConnection,_ d:Data){let t=String(data:d,encoding:.utf8) ?? "",p=(t.components(separatedBy:"\r\n").first ?? "").split(separator:" ");guard p.count>=2,p[0]=="GET"else{send(c,"405 Method Not Allowed","text/plain","Read-only foundation server");return};switch String(p[1]){case"/":send(c,"200 OK","text/html; charset=utf-8",page());case"/api/status":send(c,"200 OK","application/json","{\"service\":\"Wolffe TV\",\"phase\":\"Alpha 4.0A\",\"status\":\"running\",\"port\":\(port)}");default:send(c,"404 Not Found","text/plain","Not found")}};private func send(_ c:NWConnection,_ s:String,_ type:String,_ body:String){let b=Data(body.utf8);var x=Data("HTTP/1.1 \(s)\r\nContent-Type: \(type)\r\nContent-Length: \(b.count)\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n".utf8);x.append(b);c.send(content:x,completion:.contentProcessed{_ in c.cancel()})};private func page() -> String {
        return "<!doctype html>" +
            "<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">" +
            "<style>body{background:#100b18;color:#eee;font-family:-apple-system;display:grid;min-height:100vh;place-items:center}.c{padding:32px;border-radius:24px;background:#21182d}h1{color:#c08cff}.ok{color:#65d96e}</style>" +
            "<main class=\"c\"><h1>WOLFFE TV</h1><h2 class=\"ok\">Web server is running</h2>" +
            "<p>Alpha 4.0A.1 foundation is online on port <b>\(port)</b>.</p>" +
            "<p>TV controls are intentionally not exposed yet.</p></main>"
    }
